tool_input.content:
// Temporary verification harness for t24/game.html - deleted after the run.
const fs = require("fs"), vm = require("vm");
const PATH = "/home/zmhel/gitrepos/learn-ai/eval01/runs/.gen-work/t24/game.html";
const src = fs.readFileSync(PATH, "utf8");
const js = src.slice(src.indexOf("<script>") + 8, src.lastIndexOf("</script>"));

function mk(){
  const e = {
    _h:"", style:{cssText:""}, value:"", hidden:false, textContent:"", tagName:"DIV",
    addEventListener(){}, setAttribute(){}, getAttribute(){ return null; },
    hasAttribute(){ return false; }, querySelector(){ return mk(); },
    querySelectorAll(){ return []; }, focus(){}, select(){}, remove(){}, appendChild(){},
    closest(){ return null; },
    getBoundingClientRect(){ return {left:0,top:0,right:0,bottom:0,width:0,height:0}; }
  };
  Object.defineProperty(e, "innerHTML", { get(){ return e._h; }, set(v){ e._h = v; } });
  return e;
}
const cache = {};
const document = {
  getElementById(id){ return cache[id] || (cache[id] = mk()); },
  createElement(){ return mk(); },
  addEventListener(){}, querySelectorAll(){ return []; },
  documentElement:{ outerHTML: src }, body: mk()
};
const window = { innerWidth:1200, innerHeight:800, addEventListener(){} };
const ctx = { document, window, performance:{ now: () => Date.now() }, console, setTimeout, clearTimeout };
vm.createContext(ctx);

try {
  vm.runInContext(js, ctx, { filename:"ashfall.js" });
  console.log("BOOT OK");
} catch (e) {
  console.log("BOOT ERROR:\n" + e.stack.split("\n").slice(0, 10).join("\n"));
  process.exit(1);
}

// 1) run the in-game test suite
vm.runInContext("runTests();", ctx);
console.log("\n" + ctx.UI.devOut);

// 2) run the benchmark
vm.runInContext("runBenchmark();", ctx);
console.log("\n" + ctx.UI.devOut);

// 3) balance probe: how does the greedy policy do over a real 60-turn game on several seeds?
const probe = vm.runInContext(`(function(){
  const out = [];
  for (const s of [1337, 42, 2024, 90210, 7]){
    const g = newGame(s);
    for (let n = 0; n < 60 && pop(g) > 0 && !g.over; n++) policyTurn(g);
    out.push({ seed:s, turn:g.turn, pop:pop(g), house:housing(g), mor:avgMorale(g),
               res:g.research.length, streak:g.needStreak, outcome:g.outcome,
               score:scoreOf(g).total, food:g.res.food, water:g.res.water,
               scrip:g.res.scrip, parts:g.res.parts, metal:g.res.metal,
               blds:g.map.filter(t=>t.b).length });
  }
  return out;
})()`, ctx);
console.log("\nGREEDY POLICY, 60-TURN GAMES (win needs pop>=12 and streak>=3):");
for (const r of probe) console.log(JSON.stringify(r));

// 4) do-nothing probe: the game must be losable
const idle = vm.runInContext(`(function(){
  const g = newGame(1337); g.sandbox = false;
  for (let n = 0; n < 60 && !g.over; n++) stepTurn(g, policyChooser);
  return { turn:g.turn, pop:pop(g), outcome:g.outcome };
})()`, ctx);
console.log("\nDO-NOTHING RUN (no assignments, no builds):", JSON.stringify(idle));
